-- DBC files: WoW class 13 (Necromancer, file token NECROMANCER) copied from class 9 at creation
-- (decisions.md 2026-10-12; docs/contracts/monk-class.md). Idempotent: every table's class rows are
-- deleted first. Rows for a class above the core's class limit are skipped with a log line until core
-- patch 0024 raises it.
SET NAMES utf8mb4;
DELETE FROM `chrclasses_dbc` WHERE `ID`=13;
DELETE FROM `playercreateinfo` WHERE `class`=13;
SELECT `race`,13,`map`,`zone`,`position_x`,`position_y`,`position_z`,`orientation` FROM `playercreateinfo` WHERE `class`=9 AND `race` IN (1,2,3,4,5,6,7,8,10,11);
DELETE FROM `playercreateinfo_action` WHERE `class`=13;
SELECT `race`,13,`button`,`action`,`type` FROM `playercreateinfo_action` WHERE `class`=9 AND `action`=6603 AND `race` IN (1,2,3,4,5,6,7,8,10,11);
SELECT r.`race`,13,h.`map_id`,h.`area_id`,h.`x`,h.`y`,h.`z`,h.`o` FROM (SELECT 3 AS `race` UNION ALL SELECT 4 UNION ALL SELECT 6 UNION ALL SELECT 8 UNION ALL SELECT 11) r JOIN `dc_world_hub` h ON h.`id`=1
ON DUPLICATE KEY UPDATE `map`=VALUES(`map`),`zone`=VALUES(`zone`),`position_x`=VALUES(`position_x`),`position_y`=VALUES(`position_y`),`position_z`=VALUES(`position_z`),`orientation`=VALUES(`orientation`);
